}

// ── TZ-015: Voyage Calculator ──

export interface VoyageEstimation {
  grossFreight: number;
  commission: number;
  netFreight: number;
  totalDays: number;
  seaDays: number;
  portDays: number;
  canalDays: number;
  bunkerCost: number;
  portCosts: number;
  canalTolls: number;
  euEts?: number;
  tce: number;
